package com.yeyamo_mobile.api.moderation_trust_service.interfaces.rest;import java.time.Instant;import java.util.UUID;import com.yeyamo_mobile.api.moderation_trust_service.domain.model.*;
public record ReportResponse(UUID id,TargetType targetType,String targetId,String targetOwnerId,String reporterId,ReportReason reason,String details,ReportStatus status,String assignedTo,String resolution,Instant createdAt,Instant updatedAt,Instant decidedAt,long version){public static ReportResponse from(ModerationReport r){return new ReportResponse(r.getId(),r.getTargetType(),r.getTargetId(),r.getTargetOwnerId(),r.getReporterId(),r.getReason(),r.getDetails(),r.getStatus(),r.getAssignedTo(),r.getResolution(),r.getCreatedAt(),r.getUpdatedAt(),r.getDecidedAt(),r.getVersion());}}
